import{auth,db}from"./firebase.js";import{doc,setDoc}from"https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";import{sendEmailVerification}from"https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";const PASSWORD_PROVIDER_ID="password";export function requiresEmailVerification(e){return!!e&&((e.providerData||[]).some(e=>"password"===e.providerId)&&!e.emailVerified)}export function getEmailActionSettings(){const e=window.location.origin;return{url:`${e&&"null"!==e?e:"https://forgex-2026.firebaseapp.com"}/signIn.html?verified=1`,handleCodeInApp:!1}}export async function sendVerificationEmail(e){return sendEmailVerification(e,getEmailActionSettings())}export async function syncUserVerificationStatus(e){if(e)try{await setDoc(doc(db,"users",e.uid),{email:e.email||"",emailVerified:!!e.emailVerified,verificationSyncedAt:new Date},{merge:!0})}catch(e){console.error("Failed to sync email verification status:",e)}}export async function refreshAndSyncCurrentUser(){const e=auth.currentUser;return e?(await e.reload(),await syncUserVerificationStatus(auth.currentUser),auth.currentUser):null}